import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const LoginForm = () => {
  const [registrationId, setRegistrationId] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // Simulate API call with a timeout
      await new Promise(resolve => setTimeout(resolve, 800));

      // Dummy list of valid registration IDs (you'll replace this later)
      const validIds = ['REG123', 'REG456', 'REG789'];

      if (validIds.includes(registrationId.trim().toUpperCase())) {
        // Store the registration ID in localStorage or sessionStorage
        sessionStorage.setItem('userRegistrationId', registrationId.trim().toUpperCase());
        navigate('/vote'); // redirect to voting page
      } else {
        setError('Invalid Registration ID. Please try again.');
      }
    } catch (err) {
      setError('Login failed. Please try again later.');
      console.error('Login error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container py-5">
      <div className="row justify-content-center">
        <div className="col-md-6 col-lg-5">
          <div className="card shadow">
            <div className="card-header bg-primary text-white text-center py-3">
              <h3 className="mb-0">UniVote - Student Login</h3>
            </div>
            <div className="card-body p-4">
              <form onSubmit={handleLogin}>
                <div className="mb-4">
                  <label htmlFor="registrationId" className="form-label">Registration ID</label>
                  <input
                    type="text"
                    className="form-control form-control-lg"
                    id="registrationId"
                    placeholder="Enter your registration ID"
                    value={registrationId}
                    onChange={(e) => setRegistrationId(e.target.value)}
                    required
                    autoFocus
                  />
                  <div className="form-text">
                    Please enter your student registration ID provided by the university.
                  </div>
                </div>
                
                {error && (
                  <div className="alert alert-danger" role="alert">
                    <i className="bi bi-exclamation-triangle-fill me-2"></i>
                    {error}
                  </div>
                )}
                
                <button 
                  type="submit" 
                  className="btn btn-primary btn-lg w-100" 
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                      Logging in...
                    </>
                  ) : 'Login'}
                </button>
              </form>
            </div>
            <div className="card-footer bg-light text-center py-3">
              <div className="small">
                Having trouble? Contact <a href="mailto:support@univote.edu">support@univote.edu</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginForm;
